{"path":"/workspace/source/packages/database/migrations/009_customer_erasure.sql","command":"create","file_text":"CREATE TABLE IF NOT EXISTS operations.erasure_requests(
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  merchant_id uuid NOT NULL,
  customer_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','failed','completed')),
  attempts integer NOT NULL DEFAULT 0,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  UNIQUE(customer_id)
);

CREATE INDEX IF NOT EXISTS erasure_requests_by_merchant
  ON operations.erasure_requests(merchant_id,created_at DESC);

CREATE TABLE IF NOT EXISTS operations.privacy_tombstones(
  customer_id uuid PRIMARY KEY,
  merchant_id uuid NOT NULL,
  erasure_request_id uuid NOT NULL REFERENCES operations.erasure_requests(id),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS privacy_tombstones_by_merchant
  ON operations.privacy_tombstones(merchant_id,customer_id);
"}

{"path":"/workspace/source/packages/operations/src/idempotency.ts","command":"create","file_text":"import { createHash } from 'node:crypto';
import type pg from 'pg';

export function requestHash(value: unknown): string {
  return createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

export async function reserveIdempotency(
  client: pg.PoolClient,
  merchantId: string,
  scope: string,
  key: string,
  hash: string,
): Promise<{ status: number; body: unknown } | undefined> {
  const inserted = await client.query(
    `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
     VALUES($1,$2,$3,$4,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
    [merchantId, scope, key, hash],
  );
  if (inserted.rowCount) return undefined;
  const existing = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
    `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
     WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`, [merchantId, scope, key],
  );
  const row = existing.rows[0];
  if (!row || row.request_hash !== hash) throw Object.assign(new Error('idempotency key reused with different request'), { statusCode: 409 });
  if (row.response_status === null) throw Object.assign(new Error('request with this idempotency key is in progress'), { statusCode: 409 });
  return { status: row.response_status, body: row.response_body };
}

export async function completeIdempotency(
  client: pg.PoolClient, merchantId: string, scope: string, key: string, status: number, body: unknown,
): Promise<void> {
  await client.query(
    `UPDATE operations.idempotency_keys SET response_status=$4,response_body=$5
     WHERE merchant_id=$1 AND scope=$2 AND key=$3`, [merchantId, scope, key, status, body],
  );
}
"}

{"path":"/workspace/source/packages/privacy/src/redaction.ts","command":"create","file_text":"const PII_KEYS = new Set([
  'email',
  'name',
  'phone',
  'customerEmail',
  'customer_email',
  'billingName',
  'billing_name',
  'billingAddress',
  'billing_address',
  'externalReference',
  'external_reference',
  'line1',
  'line2',
  'city',
  'region',
  'postalCode',
  'postal_code',
  'destination',
  'text_body',
  'html_body',
  'textBody',
  'htmlBody',
]);

const CUSTOMER_OBJECT_KEYS = new Set([
  'customer',
  'customerSnapshot',
  'customer_snapshot',
  'billing_snapshot',
]);

export function anonymizedEmail(customerId: string): string {
  return `erased-${customerId}@erased.invalid`;
}

export function anonymizedExternalReference(customerId: string): string {
  return `erased-${customerId}`;
}

export function anonymizedDisplayName(): string {
  return 'Erased Customer';
}

export function redactedCustomerRecord(customerId: string): Record<string, unknown> {
  return {
    id: customerId,
    status: 'erased',
    email: anonymizedEmail(customerId),
    name: anonymizedDisplayName(),
    phone: null,
    external_reference: anonymizedExternalReference(customerId),
    metadata: {},
  };
}

export function mapErasureError(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error);
  if (message.startsWith('mailpit_') || message.includes('mailpit')) return 'mail_provider_unavailable';
  if (message.includes('opensearch') || message.includes('search_index')) return 'search_index_unavailable';
  if (message.includes('ECONNREFUSED') && message.includes('6379')) return 'cache_unavailable';
  if (message.includes('minio') || message.includes('S3') || message.includes('object_store')) return 'object_store_unavailable';
  return 'erasure_failed';
}

export function redactPii(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(redactPii);
  if (!value || typeof value !== 'object') return value;
  const input = value as Record<string, unknown>;
  const output: Record<string, unknown> = {};
  for (const [key, nested] of Object.entries(input)) {
    if (PII_KEYS.has(key) || key.toLowerCase().includes('email')) {
      output[key] = null;
      continue;
    }
    if (CUSTOMER_OBJECT_KEYS.has(key)) {
      output[key] = redactCustomerObject(nested);
      continue;
    }
    output[key] = redactPii(nested);
  }
  return output;
}

function redactCustomerObject(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return { status: 'erased' };
  const input = value as Record<string, unknown>;
  const id = typeof input.id === 'string' ? input.id : undefined;
  return id ? { id, status: 'erased' } : { status: 'erased' };
}

export interface PublicErasureRequest {
  id: string;
  customerId: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: PublicErasureRequest['status'];
  attempts: number;
  last_error: string | null;
  created_at: Date | string;
  updated_at: Date | string;
  completed_at: Date | string | null;
}

export function toPublicErasureRequest(row: ErasureRequestRow): PublicErasureRequest {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: toIso(row.created_at),
    updatedAt: toIso(row.updated_at),
    completedAt: row.completed_at ? toIso(row.completed_at) : null,
    lastError: row.last_error,
  };
}

function toIso(value: Date | string): string {
  return value instanceof Date ? value.toISOString() : new Date(value).toISOString();
}
"}

